-- ══════════════════════════════════════════════════
-- 🎮 竹仁國小帳號密碼練習遊戲 — Supabase 初始化腳本
-- ══════════════════════════════════════════════════

-- 1. 建立學生資料表
CREATE TABLE IF NOT EXISTS public.students (
    id BIGSERIAL PRIMARY KEY,
    class_name TEXT NOT NULL,
    seat_number TEXT NOT NULL,
    name TEXT NOT NULL,
    cjes_account TEXT NOT NULL,
    cjes_password TEXT NOT NULL,
    acc_hash TEXT NOT NULL,
    pwd_hash TEXT NOT NULL,
    acc_len INT NOT NULL,
    pwd_len INT NOT NULL,
    acc_hint TEXT NOT NULL,
    pwd_hint TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. 建立成績記錄與排行榜表
CREATE TABLE IF NOT EXISTS public.scores (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT REFERENCES public.students(id) ON DELETE CASCADE,
    student_name TEXT NOT NULL,
    class_name TEXT NOT NULL,
    score INT NOT NULL DEFAULT 0,
    rounds INT NOT NULL DEFAULT 0,
    accuracy NUMERIC(5,2) NOT NULL DEFAULT 100.00,
    time_limit INT NOT NULL DEFAULT 60,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. 建立索引加速查詢
CREATE INDEX IF NOT EXISTS idx_students_class ON public.students(class_name);
CREATE INDEX IF NOT EXISTS idx_scores_timelimit ON public.scores(time_limit);
CREATE INDEX IF NOT EXISTS idx_scores_score ON public.scores(score DESC);

-- 4. 啟用 Row Level Security (RLS) 並開放存取權限
ALTER TABLE public.students ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.scores ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public read students" ON public.students;
CREATE POLICY "Allow public read students" ON public.students FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow public insert students" ON public.students;
CREATE POLICY "Allow public insert students" ON public.students FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Allow public delete students" ON public.students;
CREATE POLICY "Allow public delete students" ON public.students FOR DELETE USING (true);

DROP POLICY IF EXISTS "Allow public all scores" ON public.scores;
CREATE POLICY "Allow public all scores" ON public.scores FOR ALL USING (true) WITH CHECK (true);

-- 5. 匯入 733 位學生資料
ON CONFLICT (id) DO NOTHING;

-- 調整序列起始值
SELECT setval('students_id_seq', (SELECT MAX(id) FROM public.students));
